parameters.jsCode:
const rows = $input.all().map(i => i.json);

if (!rows.length) {
  return [];
}

function normalisePlatform(platform) {
  const p = String(platform || '').toLowerCase();

  if (p === 'whatsapp') return 'whatsapp';
  if (p === 'instagram') return 'instagram';
  if (p === 'messenger' || p === 'facebook') return 'messenger';

  return 'unknown';
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function groupByConversation(list) {
  const map = new Map();

  for (const r of list) {
    const key =
      r.contact_key ||
      String(r.conversation_id || 'unknown');

    if (!map.has(key)) {
      map.set(key, {
        customer_name: r.customer_name || 'Unknown',
        contact_key: r.contact_key || '-',
        messages: []
      });
    }

    map.get(key).messages.push(
      r.message || '[No text]'
    );
  }

  return [...map.values()];
}

function renderGroups(groups) {
  if (!groups.length) {
    return '<p style="color:#777;">None</p>';
  }

  return groups.map((g, index) => {
    const messages = g.messages
      .map(m => `<li>${escapeHtml(m)}</li>`)
      .join('');

    return `
      <div style="margin-bottom:18px;">
        <strong>${index + 1}. ${escapeHtml(g.customer_name)}</strong><br>
        Contact: ${escapeHtml(g.contact_key)}<br>
        Messages: ${g.messages.length}
        <ol>${messages}</ol>
      </div>
    `;
  }).join('');
}

function platformSection(platform, title) {
  const platformRows = rows.filter(
    r => normalisePlatform(r.platform) === platform
  );

  const newRows = platformRows.filter(
    r => r.is_new_user === true
  );

  const existingRows = platformRows.filter(
    r => r.is_new_user !== true
  );

  const newGroups = groupByConversation(newRows);
  const existingGroups = groupByConversation(existingRows);

  return `
    <hr style="margin:28px 0;">

    <h2>${title} — ${platformRows.length} messages</h2>

    <h3>NEW USERS — ${newGroups.length}</h3>
    ${renderGroups(newGroups)}

    <h3>EXISTING CHATS — ${existingGroups.length}</h3>
    ${renderGroups(existingGroups)}
  `;
}

const whatsappRows = rows.filter(
  r => normalisePlatform(r.platform) === 'whatsapp'
);

const instagramRows = rows.filter(
  r => normalisePlatform(r.platform) === 'instagram'
);

const messengerRows = rows.filter(
  r => normalisePlatform(r.platform) === 'messenger'
);

const allNewGroups = groupByConversation(
  rows.filter(r => r.is_new_user === true)
);

const allExistingGroups = groupByConversation(
  rows.filter(r => r.is_new_user !== true)
);

const now = new Date();

const html = `
<h2>📩 Medical Tourism Social Media Message Digest</h2>

<table cellpadding="7" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;">
  <tr>
    <td><strong>Total Messages</strong></td>
    <td>${rows.length}</td>
  </tr>

  <tr>
    <td><strong>WhatsApp</strong></td>
    <td>${whatsappRows.length}</td>
  </tr>

  <tr>
    <td><strong>Instagram</strong></td>
    <td>${instagramRows.length}</td>
  </tr>

  <tr>
    <td><strong>Facebook Messenger</strong></td>
    <td>${messengerRows.length}</td>
  </tr>

  <tr>
    <td><strong>New Users</strong></td>
    <td>${allNewGroups.length}</td>
  </tr>

  <tr>
    <td><strong>Existing Chats</strong></td>
    <td>${allExistingGroups.length}</td>
  </tr>
</table>

${platformSection('whatsapp', '🟢 WHATSAPP')}

${platformSection('instagram', '🟣 INSTAGRAM')}

${platformSection('messenger', '🔵 FACEBOOK MESSENGER')}

<p style="font-size:12px;color:#777;margin-top:30px;">
Generated: ${now.toISOString()}
</p>
`;

return [{
  json: {
    html,
    total_messages: rows.length,
    whatsapp_messages: whatsappRows.length,
    instagram_messages: instagramRows.length,
    messenger_messages: messengerRows.length,
    new_users: allNewGroups.length,
    existing_chats: allExistingGroups.length,
    queue_ids: rows.map(r => r.id)
  }
}];

const ids = $('Build Social Digest Email2').item.json.queue_ids || [];

return ids.map(id => ({
  json: { id }
}));

