const status = $json.body.entry?.[0]?.changes?.[0]?.value?.statuses?.[0];

if (!status) return [];

return [{
  json: {
    wamid: status.id,
    status: status.status,
    timestamp: status.timestamp
      ? new Date(Number(status.timestamp) * 1000).toISOString()
      : new Date().toISOString(),
    failure_code: status.errors?.[0]?.code || null,
    failure_message: status.errors?.[0]?.message || status.errors?.[0]?.title || null
  }
}];

const inputItem = $input.item;

const norm = $('Normalize Meta Message').first().json;

const binaryData = inputItem.binary?.data;

if (!binaryData) {
  throw new Error('Downloaded Meta media file was not found under inputItem.binary.data.');
}

const username = norm.name || 'Unknown User';
const phone = norm.contact_key;
const mediaType = norm.media_type || 'image';

const mimeType = binaryData.mimeType || 'image/jpeg';

let originalFilename = binaryData.fileName || '';

if (!originalFilename) {
  const extension =
    mimeType === 'image/png' ? '.png' :
    mimeType === 'image/webp' ? '.webp' :
    mimeType === 'image/gif' ? '.gif' :
    '.jpg';

  originalFilename = 'image' + extension;
}

return {
  json: {
    username,
    phone,
    direction: 'incoming',
    platform: norm.messaging_product,
    original_filename: originalFilename,
    mime_type: mimeType,
    media_type: mediaType
  },
  binary: {
    data: binaryData
  }
};

const body = $json.body;

const entry = body.entry?.[0];
const messaging = entry?.messaging?.[0];

if (!messaging?.message) return [];

const senderId = messaging.sender?.id;
const recipientId = messaging.recipient?.id;
const text = messaging.message?.text || '';
const isInstagram = body.object === 'instagram';

const attachment = messaging.message?.attachments?.[0];
const isImage = attachment?.type === 'image';

// Ad-click referral (Click-to-Messenger / Click-to-Instagram ads). Meta puts it on the
// first message (message.referral) or on its own (messaging.referral).
const rawRef = messaging.message?.referral || messaging.referral || null;
const adCtx = rawRef?.ads_context_data || {};
const referral = rawRef ? JSON.stringify({
  source: rawRef.source || null,
  type: rawRef.type || null,
  ref: rawRef.ref || null,
  ad_id: rawRef.ad_id || null,
  headline: adCtx.ad_title || null,
  image_url: adCtx.photo_url || null,
  video_url: adCtx.video_url || null,
  post_id: adCtx.post_id || null,
  source_url: rawRef.source_url || null,
  raw: rawRef
}) : null;

return [{
  json: {
    phone: isInstagram ? `ig_${senderId}` : `fb_${senderId}`,
    contact_key: isInstagram ? `ig_${senderId}` : `fb_${senderId}`,
    meta_psid: senderId,
    meta_recipient_id: recipientId,
    message: text,
    name: isInstagram ? `Instagram User ${senderId}` : `Facebook User ${senderId}`,
    messaging_product: isInstagram ? 'instagram' : 'messenger',
    is_image: isImage,
    media_url: isImage ? (attachment.payload?.url || null) : null,
    media_type: attachment?.type || null,
    referral
  }
}];

const conv = $('Get Rows By Phone').item.json;

/*
 * Detect the actual incoming channel.
 *
 * Internal channel names:
 * whatsapp  = WhatsApp
 * instagram = Instagram
 * messenger = Facebook Messenger
 */
let channel =
  String(conv?.platform || '')
    .trim()
    .toLowerCase();

if (channel === 'facebook' || channel === 'fb') {
  channel = 'messenger';
}

/*
 * Fallback to the current incoming normalisation node
 * if the conversation platform is unavailable.
 */
if (
  !['whatsapp', 'instagram', 'messenger']
    .includes(channel)
) {
  try {
    channel =
      $('Normalize Meta Message').isExecuted
        ? $('Normalize Meta Message').item.json.messaging_product
        : $('Edit Fields').item.json.messaging_product;
  } catch (e) {
    channel = '';
  }
}

channel =
  String(channel || '')
    .trim()
    .toLowerCase();

const isWhatsApp =
  channel === 'whatsapp';

/*
 * Only a WhatsApp sender ID is a usable contact number.
 *
 * Instagram/Facebook values such as ig_123 or fb_123
 * must never be treated as telephone numbers.
 */
const detectedContactNumber =
  isWhatsApp &&
  /^\+\d{7,15}$/.test(
    String(conv?.phone || '').trim()
  )
    ? String(conv.phone).trim()
    : null;

/*
 * Number previously confirmed or supplied by the user.
 */
const savedContactNumber =
  conv?.whatsapp_phone
    ? String(conv.whatsapp_phone).trim()
    : null;

let userMessage = '';

try {
  if ($('Use Re-engagement Original Message').isExecuted) {
    userMessage =
      $('Use Re-engagement Original Message').item.json.message || '';
  } else if ($('Normalize Meta Message').isExecuted) {
    userMessage =
      $('Normalize Meta Message').item.json.message || '';
  } else {
    userMessage =
      $('Edit Fields').item.json.message || '';
  }
} catch (e) {
  userMessage = $input.item.json.message || '';
}

const msgs = $('Get Recent Messages').all()
  .map(item => item.json)
  .filter(m => m && typeof m.id !== 'undefined');

const wasOptedOut = conv?.opted_out === true;

const lastIncoming = conv?.last_incoming_at ? new Date(conv.last_incoming_at) : null;
const now = new Date();
const hoursSince = lastIncoming ? (now - lastIncoming) / (1000 * 60 * 60) : Infinity;

const isReturningUser = !wasOptedOut && msgs.length > 1 && hoursSince > 4;

const previousEnquiry = isReturningUser ? {
  condition: conv.condition,
  destination: conv.destination,
  status: conv.status
} : null;

let recent_history = '';
let recentHistoryError = null;
try {
  if (Array.isArray(msgs) && msgs.length > 0) {
    msgs.reverse();
    const lines = msgs
      .filter(m => m.message && m.message.trim())
      .map(m => {
        if (m.sender === 'incoming') return 'Customer: ' + m.message.trim();
        if (m.sender_type === 'human') return 'Agent (' + (m.agent_name || 'Human') + '): ' + m.message.trim();
        return 'Bot: ' + m.message.trim();
      });
    if (lines.length > 0) recent_history = lines.join(String.fromCharCode(10));
  }
} catch(e) {
  recentHistoryError = (e && e.message) ? e.message : String(e);
}

return [{
  json: {
    recent_history_error: recentHistoryError,
    /*
     * Internal conversation identifier.
     * For Instagram/Facebook this may be ig_... or fb_...
     * and must not be treated as a telephone number.
     */
    phone: conv?.phone || '',

    channel,

    /*
     * Available only when the incoming channel is WhatsApp.
     */
    detected_contact_number:
      detectedContactNumber,

    /*
     * A number previously confirmed or manually provided.
     */
    saved_contact_number:
      savedContactNumber,

    is_returning_user:
      isReturningUser,

    contact_person: {
      name:
        isReturningUser
          ? conv?.name || null
          : null,

      /*
       * Always return a number already stored in the database,
       * even during the current enquiry.
       */
      phone:
        savedContactNumber
    },

    previous_enquiry:
      previousEnquiry,

    user_id:
      conv?.id || null,

    message:
      userMessage,

    recent_history:
      recent_history || null
  }
}];

const inputItem = $input.item;

const payload =
  $('Is Image or Document?')
    .first()
    .json
    .body
    .entry[0]
    .changes[0]
    .value;

const message = payload.messages[0];
const contact = payload.contacts[0];

const binaryData =
  inputItem.binary?.data;

if (!binaryData) {
  throw new Error(
    'Downloaded WhatsApp file was not found under inputItem.binary.data.'
  );
}

const username =
  contact.profile?.name ||
  'Unknown User';

const phone =
  '+' + contact.wa_id;

const mediaType =
  message.type;

const mimeType =
  message.image?.mime_type ||
  message.document?.mime_type ||
  binaryData.mimeType ||
  'application/octet-stream';

let originalFilename =
  message.document?.filename ||
  binaryData.fileName ||
  '';

if (!originalFilename) {
  if (mediaType === 'image') {
    const extension =
      mimeType === 'image/png' ? '.png' :
      mimeType === 'image/webp' ? '.webp' :
      mimeType === 'image/gif' ? '.gif' :
      '.jpg';

    originalFilename =
      'image' + extension;
  } else {
    originalFilename =
      'document';
  }
}

return {
  json: {
    username,
    phone,
    direction: 'incoming',
    platform: 'whatsapp',
    original_filename: originalFilename,
    mime_type: mimeType,
    media_type: mediaType
  },
  binary: {
    data: binaryData
  }
};

// Parse AI Agent output: extract WhatsApp message and INTEL JSON
const raw = $input.first().json.output || '';

// Extract <WHATSAPP> block
const waMatch = raw.match(/<WHATSAPP>([\s\S]*?)<\/WHATSAPP>/i);
const whatsapp_message = waMatch
  ? waMatch[1].trim()
  : raw.replace(/<INTEL>[\s\S]*?<\/INTEL>/gi, '').trim();

// Extract <INTEL> block
const intelMatch = raw.match(/<INTEL>([\s\S]*?)<\/INTEL>/i);
let intel = {};
let parseError = null;

if (intelMatch) {
  try {
    intel = JSON.parse(intelMatch[1].trim());
  } catch (e) {
    parseError = e.message;
    intel = { parse_error: e.message };
  }
}

const route           = intel.route || (intel.escalate === true ? 'escalated' : 'normal');
const escalate        = route === 'escalated';
const escalate_reason = intel.escalate_reason || null;
const contact_person_name    = intel.contact_person?.name  || null;
const contact_person_phone   = intel.contact_person?.phone || null;
const contact_method  = intel.contact_person?.contact_method || null;
const patient_name      = intel.patient?.name || null;
const enquiry_condition = intel.enquiry?.condition || null;
const current_step    = intel.step || null;
const lang            = intel.lang || 'id';
const user_persona    = intel.user_persona || null;
const is_returning_user = intel.is_returning_user || false;

return [{
  json: {
    whatsapp_message,
    intel,
    route,
    escalate,
    escalate_reason,
    contact_person_name,
    contact_person_phone,
    contact_method,
    patient_name,
    enquiry_condition,
    current_step,
    lang,
    user_persona,
    is_returning_user,
    parse_error: parseError
  }
}];

