 */
if (
  !['whatsapp', 'instagram', 'messenger']
    .includes(channel)
) {
  try {
    channel =
      $('Normalize Meta Message2').isExecuted
        ? $('Normalize Meta Message2').item.json.messaging_product
        : $('Edit Fields2').item.json.messaging_product;
  } catch (e) {
    channel = '';
  }
}

channel =
  String(channel || '')
    .trim()
    .toLowerCase();

const isWhatsApp =
  channel === 'whatsapp';

/*
 * Only a WhatsApp sender ID is a usable contact number.
 *
 * Instagram/Facebook values such as ig_123 or fb_123
 * must never be treated as telephone numbers.
 */
const detectedContactNumber =
  isWhatsApp &&
  /^\+\d{7,15}$/.test(
    String(conv?.phone || '').trim()
  )
    ? String(conv.phone).trim()
    : null;

/*
 * Number previously confirmed or supplied by the user.
 */
const savedContactNumber =
  conv?.whatsapp_phone
    ? String(conv.whatsapp_phone).trim()
    : null;

let userMessage = '';

try {
  if ($('Use Re-engagement Original Message1').isExecuted) {
    userMessage =
      $('Use Re-engagement Original Message1').item.json.message || '';
  } else if ($('Normalize Meta Message2').isExecuted) {
    userMessage =
      $('Normalize Meta Message2').item.json.message || '';
  } else {
    userMessage =
      $('Edit Fields2').item.json.message || '';
  }
} catch (e) {
  userMessage = $input.item.json.message || '';
}

const msgs = $('Get Recent Messages2').all()
  .map(item => item.json)
  .filter(m => m && typeof m.id !== 'undefined');

const wasOptedOut = conv?.opted_out === true;

const lastIncoming = conv?.last_incoming_at ? new Date(conv.last_incoming_at) : null;
const now = new Date();
const hoursSince = lastIncoming ? (now - lastIncoming) / (1000 * 60 * 60) : Infinity;

const isReturningUser = !wasOptedOut && msgs.length > 1 && hoursSince > 4;

const previousEnquiry = isReturningUser ? {
  condition: conv.condition,
  destination: conv.destination,
  status: conv.status
} : null;

let recent_history = '';
let recentHistoryError = null;
try {
  if (Array.isArray(msgs) && msgs.length > 0) {
    msgs.reverse();
    const lines = msgs
      .filter(m => m.message && m.message.trim())
      .map(m => {
        if (m.sender === 'incoming') return 'Customer: ' + m.message.trim();
        if (m.sender_type === 'human') return 'Agent (' + (m.agent_name || 'Human') + '): ' + m.message.trim();
        return 'Bot: ' + m.message.trim();
      });
    if (lines.length > 0) recent_history = lines.join(String.fromCharCode(10));
  }
} catch(e) {
  recentHistoryError = (e && e.message) ? e.message : String(e);
}

return [{
  json: {
    recent_history_error: recentHistoryError,
    /*
     * Internal conversation identifier.
     * For Instagram/Facebook this may be ig_... or fb_...
     * and must not be treated as a telephone number.
     */
    phone: conv?.phone || '',

    channel,

    /*
     * Available only when the incoming channel is WhatsApp.
     */
    detected_contact_number:
      detectedContactNumber,

    /*
     * A number previously confirmed or manually provided.
     */
    saved_contact_number:
      savedContactNumber,

    is_returning_user:
      isReturningUser,

    contact_person: {
      name:
        isReturningUser
          ? conv?.name || null
          : null,

      /*
       * Always return a number already stored in the database,
       * even during the current enquiry.
       */
      phone:
        savedContactNumber
    },

    previous_enquiry:
      previousEnquiry,

    user_id:
      conv?.id || null,

    message:
      userMessage,

    recent_history:
      recent_history || null
  }
}];

const inputItem = $input.item;

const payload =
  $('Is Image or Document?2')
    .first()
    .json
    .body
    .entry[0]
    .changes[0]
    .value;

const message = payload.messages[0];
const contact = payload.contacts[0];

const binaryData =
  inputItem.binary?.data;

if (!binaryData) {
  throw new Error(
    'Downloaded WhatsApp file was not found under inputItem.binary.data.'
  );
}

const username =
  contact.profile?.name ||
  'Unknown User';

const phone =
  '+' + contact.wa_id;

const mediaType =
  message.type;

const mimeType =
  message.image?.mime_type ||
  message.document?.mime_type ||
  binaryData.mimeType ||
  'application/octet-stream';

let originalFilename =
  message.document?.filename ||
  binaryData.fileName ||
  '';

if (!originalFilename) {
  if (mediaType === 'image') {
    const extension =
      mimeType === 'image/png' ? '.png' :
      mimeType === 'image/webp' ? '.webp' :
      mimeType === 'image/gif' ? '.gif' :
      '.jpg';

    originalFilename =
      'image' + extension;
  } else {
    originalFilename =
      'document';
  }
}

return {
  json: {
    username,
    phone,
    direction: 'incoming',
    platform: 'whatsapp',
    original_filename: originalFilename,
    mime_type: mimeType,
    media_type: mediaType
  },
  binary: {
    data: binaryData
  }
};

// Parse AI Agent output: extract WhatsApp message and INTEL JSON
const raw = $input.first().json.output || '';

// Extract <WHATSAPP> block
const waMatch = raw.match(/<WHATSAPP>([\s\S]*?)<\/WHATSAPP>/i);
const whatsapp_message = waMatch
  ? waMatch[1].trim()
  : raw.replace(/<INTEL>[\s\S]*?<\/INTEL>/gi, '').trim();

// Extract <INTEL> block
const intelMatch = raw.match(/<INTEL>([\s\S]*?)<\/INTEL>/i);
let intel = {};
let parseError = null;

if (intelMatch) {
  try {
    intel = JSON.parse(intelMatch[1].trim());
  } catch (e) {
    parseError = e.message;
    intel = { parse_error: e.message };
  }
}

const route           = intel.route || (intel.escalate === true ? 'escalated' : 'normal');
const escalate        = route === 'escalated';
const escalate_reason = intel.escalate_reason || null;
const contact_person_name    = intel.contact_person?.name  || null;
const contact_person_phone   = intel.contact_person?.phone || null;
const contact_method  = intel.contact_person?.contact_method || null;
const patient_name      = intel.patient?.name || null;
const enquiry_condition = intel.enquiry?.condition || null;
const current_step    = intel.step || null;
const lang            = intel.lang || 'id';
const user_persona    = intel.user_persona || null;
const is_returning_user = intel.is_returning_user || false;

return [{
  json: {
    whatsapp_message,
    intel,
    route,
    escalate,
    escalate_reason,
    contact_person_name,
    contact_person_phone,
    contact_method,
    patient_name,
    enquiry_condition,
    current_step,
    lang,
    user_persona,
    is_returning_user,
    parse_error: parseError
  }
}];

